def map_existing_contracts(apps, schema_editor):
    """Give every existing billing contract the term its dates imply and
    mark it as created before e-signatures were required.

    Mapping (psa.contract_terms.infer): no end date -> month-to-month; a
    12-month window -> annual; 24+ months in whole years -> multi-year;
    anything else -> custom fixed term of that many months. Each row also
    gets legacy_terms_hash, a fingerprint of its commercial terms now, so it
    keeps activating and billing exactly as before while those terms are not
    changed. Nothing about billing (status, amounts, dates, cadence) is
    written."""
    from psa.contract_terms import infer, terms_hash
    Contract = apps.get_model('psa', 'Contract')
    for c in Contract.objects.all().iterator():
        term_type, months = infer(c.start_date, c.end_date)
        c.term_type, c.term_months = term_type, months
        Contract.objects.filter(pk=c.pk).update(term_type=term_type, term_months=months,
                                                legacy_terms_hash=terms_hash(c))


